def create_mcp():
    "Create the nbskill FastMCP server."
    mcp = FastMCP(
        "nbskill",
        instructions=(
            "Work notebook-first in nbdev projects. Prefer read_nb/show_doc for context, "
            "write_nb/update_cell for edits, and exec_nb for visible notebook execution. "
            "Keep documentation before exported code and show-off examples after it."
        ),
    )

    @mcp.tool(name="read_nb")
    def read_nb_tool(
        path: str,
        cell_id: str | None = None,
        chapter: str | None = None,
        cell_type: str | None = None,
        contains: str | None = None,
        filter: str | None = None,
        context: int = 0,
        show_ids: bool = False,
        scope: str = "overview",
    ) -> str:
        "Read a compact, non-JSON notebook view. Use context to include docs/examples around a cell."
        return capture_call(
            _read_nb, path=path, cell_id=cell_id, chapter=chapter, cell_type=cell_type,
            contains=contains, filter=filter, context=context, show_ids=show_ids, scope=scope,
        )

    @mcp.tool(name="show_doc")
    def show_doc_tool(path: str, symbol: str, context: int = 2, source: bool = False, show_ids: bool = False) -> str:
        "Show rationale/docs, exported code, and show-off examples for a symbol."
        return capture_call(_show_doc, path=path, symbol=symbol, context=context, source=source, show_ids=show_ids)

    @mcp.tool(name="write_nb")
    def write_nb_tool(
        path: str,
        cells: str = "",
        before_id: str | None = None,
        after_id: str | None = None,
        chapter: str | None = None,
        replace: bool = False,
        cell_type: str = "code",
        export: bool = True,
        run_test: bool = False,
        run_style: bool = False,
        style_strict: bool = False,
        validate_code: bool = True,
    ) -> str:
        "Write multiline cell text directly to a notebook."
        return capture_call(
            _write_nb, path=path, cells=cells, cells_file=None, before_id=before_id, after_id=after_id,
            chapter=chapter, replace=replace, cell_type=cell_type, export=export, run_test=run_test,
            run_style=run_style, style_strict=style_strict, validate_code=validate_code,
        )

    @mcp.tool(name="update_cell")
    def update_cell_tool(
        path: str,
        new: str = "",
        cell_id: str | None = None,
        old_str: str | None = None,
        source_hash: str | None = None,
        cell_type: str = "code",
        export: bool = True,
        run_test: bool = False,
        validate_code: bool = True,
        dry_run: bool = False,
    ) -> str:
        "Update one notebook cell by id, or replace old_str inside one matching cell."
        return capture_call(
            _update_cell, path=path, new=new, new_file=None, cell_id=cell_id, old_str=old_str,
            source_hash=source_hash, cell_type=cell_type, export=export, run_test=run_test,
            validate_code=validate_code, dry_run=dry_run,
        )

    @mcp.tool(name="exec_nb")
    def exec_nb_tool(
        path: str,
        dest: str | None = None,
        exc_stop: bool = False,
        up2id: int | str | None = None,
        chapter: str | None = None,
        show_output: bool = True,
        verbose: bool = False,
    ) -> str:
        "Execute a notebook and return visible outputs/errors."
        return capture_call(
            _exec_nb, path=path, dest=dest, exc_stop=exc_stop, up2id=up2id,
            chapter=chapter, show_output=show_output, verbose=verbose,
        )

    @mcp.tool(name="diff_nb")
    def diff_nb_tool(path: str, ref_a: str | None = "HEAD", ref_b: str | None = None, adds: bool = True, changes: bool = True, dels: bool = False) -> str:
        "Diff code cells only."
        return capture_call(_diff_nb, path=path, ref_a=ref_a, ref_b=ref_b, adds=adds, changes=changes, dels=dels)

    @mcp.tool(name="apply_nb")
    def apply_nb_tool(spec_path: str = "dev/nbskill-op.toml") -> str:
        "Apply the archived TOML manifest workflow. Prefer write_nb/update_cell MCP tools when available."
        return capture_call(_apply_nb, spec_path=spec_path)

    @mcp.tool(name="chstyle")
    def chstyle_tool(path: str = ".", skip_folder_re: str | None = None, skip_path: str | None = None, strict: bool = False) -> str:
        "Print fast.ai style hints."
        return capture_call(_chstyle, path=path, skip_folder_re=skip_folder_re, skip_path=skip_path, strict=strict)

    @mcp.tool(name="py2nb")
    def py2nb_tool(path: str, nbs_path: str = "nbs", dest: str | None = None, class_lines: int = 100, method_lines: int = 10) -> str:
        "Convert a Python file into an nbdev notebook."
        return capture_call(_py2nb, path=path, nbs_path=nbs_path, dest=dest, class_lines=class_lines, method_lines=method_lines)

    @mcp.tool(name="py2nbs")
    def py2nbs_tool(path: str, nbs_path: str = "nbs", recursive: bool = True, maxdepth: int | None = None, preserve_tree: bool = True, class_lines: int = 100, method_lines: int = 10) -> str:
        "Convert Python files in a folder into nbdev notebooks."
        return capture_call(
            _py2nbs, path=path, nbs_path=nbs_path, recursive=recursive, maxdepth=maxdepth,
            preserve_tree=preserve_tree, class_lines=class_lines, method_lines=method_lines,
        )

    return mcp

